pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // Exclude the IERC165 interface (and zero) because both implementations agree it is supported.
        // The bug manifests only for the IERC1155 and IERC1155MetadataURI interfaces
        // which the reference supports but the mutant rejects.
        vm.assume(interfaceId != type(IERC165).interfaceId);
        vm.assume(interfaceId != bytes4(0));

        bytes4 ierc1155 = type(IERC1155).interfaceId;
        bytes4 ierc1155metadata = type(IERC1155MetadataURI).interfaceId;

        // Obtain actual supportsInterface results from the code under test.
        // The mutant removes overrides for IERC1155/IERC1155MetadataURI and falls through to super,
        // which only knows IERC165.
        bool actual = c.supportsInterface(interfaceId);

        // The reference behaviour (implemented by the real, non‑mutant C) is:
        //   true  for IERC1155 and IERC1155MetadataURI,
        //   false for every other interface (excluding IERC165 which we already filtered out).
        // We encode that as a simple check: the actual result should be true exactly when
        // interfaceId is one of the two ERC1155 interface IDs.
        bool expected = (interfaceId == ierc1155 || interfaceId == ierc1155metadata);
        assertTrue(actual == expected);
    }
}

