pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, uint256 id) public {
        // account can be any address, including address(0)
        // id can be any uint256
        bool refOk;
        bytes memory refReturndata;
        try c.balanceOf(account, id) returns (uint256 bal) {
            refReturndata = abi.encode(bal);
            refOk = true;
        } catch {
            refOk = false;
        }

        // If the reference call reverted, the mutant must also revert.
        // If the reference call succeeded, the mutant must succeed and return the same value.
        // We drive the comparison through a low-level call to the same address to test the mutant behavior
        // (the fuzzer evaluates the deployed C which is the mutant version).
        // Actually the test runs against the deployed C, which is the mutant. We need to check that
        // the mutant's behavior matches the expected behavior of the correct contract.
        // The correct contract reverts for account == address(0) with a specific message,
        // otherwise returns _balances[id][account].
        // The mutant returns 0 for address(0) instead of reverting.
        // So we check: if account == address(0), the call must revert; else it must succeed and return >=0.
        // We already have the actual result from the try above.
        if (account == address(0)) {
            assertTrue(!refOk); // correct contract reverts, mutant returns 0 => fails this
        } else {
            assertTrue(refOk);
        }
    }
}

