pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 id) public {
        // The fuzzer can pick any account and any id.
        // We need a token that exists in the original, so we mint one with id 0,
        // but the fuzzer may also use arbitrary ids. The difference only manifests
        // when account == address(0), so we allow the fuzzer to test any account.
        // The original reverts for address(0); the mutant returns 0.
        // We check that when the original does NOT revert, the return value is non-zero
        // (meaning the mutant must also not revert, but the mutant's return for zero address
        // would be 0, causing a mismatch in a case where the original would revert).
        // Actually, the rule: balanceOf(address(0), anyId) must revert in the original,
        // but the mutant returns 0. So if account == address(0), the original reverts;
        // the mutant succeeds. To catch this, we need a try/catch.
        // But we also need the mutant to fail the assertion on some input, not all.
        // The simplest rule that the original satisfies for all inputs:
        //   If balanceOf does not revert, then the returned balance must be >= 0 (always true).
        // OR: The call balanceOf(account, id) reverts if and only if account == address(0).
        // The original always reverts when account == address(0); the mutant never reverts and returns 0.
        // So we can assert that for account == address(0), the call must revert.
        // This is a universal property: for any id, balanceOf(address(0), id) reverts.
        // The mutant fails because it does not revert for address(0).
        // The fuzzer will eventually try account = address(0).
        // To make the test pass on the reference for ALL inputs (including non-zero accounts),
        // we only apply the revert check when account is zero. For non-zero accounts, both
        // return normally, so we accept both.
        // Implementation:
        if (account == address(0)) {
            // The original must revert.
            (bool success, ) = address(c).call(abi.encodeWithSelector(c.balanceOf.selector, account, id));
            assertTrue(!success, "Expected revert for zero address");
        }
        // For non-zero accounts, we don't care; the test passes trivially.
        // But this still tests a general rule that the original holds for all inputs.
        // This approach does not repeat previous tried patterns because we don't compare internal balances.
    }
}
